    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    if n < 10:
        c = opp.count('C')
        if c >= n - 1:
            return 'C'
        return 'D' if opp[-1] == 'D' else 'C'
    last = opp[-1]
    if last == 'D':
        return 'D'
    r = rng.random()
    if n >= 90:
        return 'D' if r < 0.75 else 'C'
    if n >= 70:
        return 'D' if r < 0.5 else 'C'
    if n >= 50:
        return 'D' if r < 0.3 else 'C'
    if n >= 30:
        return 'D' if r < 0.15 else 'C'
    return 'D' if r < 0.08 else 'C'

